// src/services/authService.js
// Mirrors: lib/supabase.js auth functions → now points to Django REST

import { post, get, saveTokens, clearTokens } from "./api";

// POST /api/auth/register/
export const registerUser = (username, password, extra = {}) =>
  post("/auth/register/", { username, password, ...extra });

// POST /api/auth/login/ — saves JWT tokens on success
export const loginUser = async (username, password) => {
  const result = await post("/auth/login/", { username, password });
  if (result.data?.access) {
    saveTokens(result.data.access, result.data.refresh);
  }
  return result;
};

// Clear tokens on logout
export const logoutUser = () => clearTokens();

// GET /api/auth/user/ — returns current authenticated user
export const getCurrentUser = () => get("/auth/user/");
